const notificationsStore = useNotificationsStore()

const { notifications } = storeToRefs(notificationsStore)

onMounted(() => {
  const stored = JSON.parse(localStorage.getItem('notifications') || '[]')

  // Системные уведомления (промо и т.д.)
  const systemNotifs = [
    {
      id: 'sys-2',
      type: 'promo',
      icon: iconPromo,
      title: 'Акция -10%',
      text: 'В честь Дня города, мы запускаем акцию на все ноутбуки. Получи <b>10% скидку.</b>',
      time: '10.06.2025, 09:00',
      link: true,
    },
    {
      id: 'sys-3',
      type: 'promo',
      icon: iconBadge,
      title: 'Новинка недели!',
      text: 'В продаже появился абсолютно новый смартфон <b>VIVO V50 5G</b>.',
      time: '09.06.2025, 10:13',
      link: true,
    },
  ]

  // Из localStorage — действия пользователя
  const userNotifs = stored.map(n => ({
    ...n,
    icon: n.title === 'Снят с продажи' ? iconMyHelp : iconHeart,
  }))

  notifications.value = [...userNotifs, ...systemNotifs]
})

const myhelpCount = computed(() =>
  notifications.value.filter(n => n.type === 'myhelp').length
)

const filteredNotifications = computed(() => {
  if (activeFilter.value === 'all') return notifications.value
  return notifications.value.filter(n => n.type === activeFilter.value)
})

const showClearSheet = ref(false)

function confirmClear() {
  notifications.value = []
  localStorage.removeItem('notifications')
  showClearSheet.value = false
}
